/* JAH interactive demo program — jahdb-demo-1.0
 * Database: maritime · Record: JAH-MAR-000014 · Aircraft carrier — fleet review CS-3866/R-10014
 * Text analysis + guided reading of this record's main text field ("description").
 * RUN ON PC: save as demo.js, then run:  node demo.js
 * RUN IN BROWSER: press F12, paste this program into the console, press Enter.
 * RUN IN-PAGE: open this record and press "Run interactive demo". */
(function(){
var TEXT="This generated study (CS-3866/R-10014, compiled 2023) examines 862 documented records concerning Aircraft carrier in a fleet review setting. The established facts remain: floating airbases that launch and recover aircraft with catapults and arresting gear The study focuses on flight deck and catapult, reporting patterns consistent with published maritime references. As a Signature-generated study record, the scenario is illustrative; the core facts about Aircraft carrier come from published maritime sources.";
var words=TEXT.split(/\s+/).filter(Boolean);
var sents=TEXT.split(/[.!?]+/).filter(function(s){return s.trim().length>10;});
console.log("=== Aircraft carrier — fleet review CS-3866/R-10014 ===");
console.log("field: description · "+words.length+" words · "+sents.length+" sentences · ~"+Math.max(1,Math.round(words.length/200))+" min read");
console.log("top words: study, aircraft, carrier, facts, with, published, maritime, 2023");
console.log("--- guided read (first 5 sentences) ---");
sents.slice(0,5).forEach(function(s,i){console.log((i+1)+". "+s.trim().slice(0,160));});
if(sents.length>5)console.log("… +"+(sents.length-5)+" more sentences in the full record.");
})();
